3	/**
4	 * How MHPCO settles a damage report against a policy.
5	 *
6	 * This module owns the office's claims rulings: what it deducts from every
7	 * damage event and what it is willing to reimburse. It knows nothing about
8	 * premiums — a policy costs what it costs, and a claim pays what it pays.
9	 */
10	
11	/** A single damaged item in a damage report. */
12	export interface Damage {
13	  readonly itemType: string;
14	  readonly amount: number;
15	}
16	
17	/** A damage report submitted against a policy. */
18	export interface Incident {
19	  readonly cause: string;
20	  readonly damages: readonly Damage[];
21	}
22	
23	/**
24	 * MHPCO reimburses damage to a highly enchanted item at half its amount: such
25	 * an item is held to be beyond the office's ordinary means of restoration.
26	 */
27	const HALF_REIMBURSEMENT_FROM_ENCHANTMENT = 8;
28	const HALF = 0.5;
29	
30	/** The share of a damage amount MHPCO accepts before taking its deductible. */
31	function acceptedShare(damagedItem: Item): number {
32	  return (damagedItem.enchantment ?? 0) >= HALF_REIMBURSEMENT_FROM_ENCHANTMENT ? HALF : 1;
33	}
34	
35	/** MHPCO deducts a fixed excess from every damage event it settles. */
36	const DEDUCTIBLE_G = 100;
37	
38	/**
39	 * What MHPCO reimburses for a single damaged item: the share of the damage its
40	 * clauses accept, less the deductible it keeps on every damage event.
41	 */
42	export function damageReimbursement(damage: Damage, damagedItem: Item): number {
43	  return damage.amount * acceptedShare(damagedItem) - DEDUCTIBLE_G;
44	}
